+                ) },
+            new Object[] {
+                new Test(
+                    """
+                        FROM idx | EVAL ip = to_ip(host), x = to_string(host), y = to_string(host)
+                        | WHERE id is not null AND id > 100 AND host RLIKE \".*foo\"
+                        | eval a = 10
+                        | drop host
+                        | rename a as foo
+                        | DROP foo
+                        """, // lowercase on purpose
+                    Map.ofEntries(
+                        Map.entry("FROM", 1),
+                        Map.entry("EVAL", 2),
+                        Map.entry("WHERE", 1),
+                        Map.entry("DROP", 2),
+                        Map.entry("RENAME", 1)
+                    ),
+                    Map.ofEntries(Map.entry("TO_IP", 1), Map.entry("TO_STRING", 2)),
+                    true
+                ) },
